arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo "before-fix exit $?"
sed -i 's|(\$1 \* 90 + 99) / 100|$1 * 90 / 100|' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo "after-fix exit $?"
grep -rn "90 + 99" . --exclude-dir=.git | wc -l
mkdir -p notes && printf '# PRC-412\nCause: f02b252 "tidy up rounding" changed floor to ceil in bin/price, bin/quote, lib/invoice.sh.\nFix: restored $1 * 90 / 100 in all three; tests added for 999.\n' > notes/PRC-412.md
git add -A && git commit -qm "PRC-412: restore round-down for member price (price, quote, invoice)

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>" && git log --oneline -1

